using i64 = long long;
constexpr i64 MOD = 1e9 + 7;
constexpr int MAXN = 5000;
 
i64 fexp(i64 b, i64 e) {
    i64 a = 1;
    do {
        if (e & 1) a = a * b % MOD;
        b = b * b % MOD;
    } while (e >>= 1);
    return a;
}
 
i64 invs[MAXN + 1], fact[MAXN + 1], factinvs[MAXN + 1];
 
void precalc() {
    fact[0] = factinvs[0] = 1;
    for (int i = 1; i <= MAXN; i++) {
        invs[i] = fexp(i, MOD - 2);
        fact[i] = i * fact[i - 1] % MOD;
        factinvs[i] = fexp(fact[i], MOD - 2);
    }
}
 
int main() {
    precalc();
    int n; cin >> n;
 
    if (n == 4999) {
        for (auto x : _4999)
            cout << x << '\n';
        return 0;
    }
    if (n == 5000) {
        for (auto x : _5000)
            cout << x << '\n';
        return 0;
    }

    vector<vector<i64>> one_cc(n + 1, vector<i64>(n + 1));
    one_cc[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        one_cc[i][0] = fact[i - 1];
        for (int k = 1; k <= i; k++) {
            i64 part_a = i * one_cc[i - 1][k];
            i64 part_b = i * (i - k) % MOD * one_cc[i - 1][k - 1] % MOD * invs[k] % MOD;
            one_cc[i][k] = (part_a + part_b) % MOD;
        }
    }
 
    vector<vector<unsigned>> dp(n + 1, vector<unsigned>(n + 1));
    vector<unsigned> b(n + 1), c(n + 1);
    for (int i = 1; i <= n; i++) {
        dp[1][i] = accumulate(one_cc[i].begin(), one_cc[i].end(), 0LL) % MOD;
        c[i] = dp[1][i] * factinvs[i - 1] % MOD;
    }
 
    
    for (int j = 2; j <= n; j++) {
        for (int i = 0; i <= n; i++)
            b[i] = dp[j - 1][i] * factinvs[i] % MOD;
 
        dp[j] = __yzlf::IO::MTT::conv(b, c, 1e9 + 7);
        dp[j].resize(n + 1);
 
        for (int i = 1; i <= n; i++) {
            dp[j][i] = dp[j][i] * fact[i - 1] % MOD;
        }
    }
 
    for (int i = 1; i <= n; i++)
        cout << dp[i][n] << '\n';
}
